'use client'

import { useState } from 'react'

export type PendingRequest = {
  id: string
  fullName: string
  phone: string | null
  children: string[]
  team: string | null
  academy: string | null
}

export function RequestList({ initial }: { initial: PendingRequest[] }) {
  const [rows, setRows] = useState(initial)
  const [busyId, setBusyId] = useState<string | null>(null)
  const [error, setError] = useState<string | null>(null)

  async function decide(id: string, decision: 'approve' | 'decline') {
    // The row goes the moment the coach decides (the "Feels instant" pass):
    // the route behind it is a dozen writes from a server across the
    // Pacific, and a coach should not watch "Working…" for them. It comes
    // back, with a sentence, if the database said no.
    const row = rows.find((x) => x.id === id)
    const was = rows
    setBusyId(id)
    setError(null)
    setRows((r) => r.filter((x) => x.id !== id))

    const res = await fetch('/api/join/approve', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ requestId: id, decision }),
    }).catch(() => null)

    setBusyId(null)
    if (!res || !res.ok) {
      const body = res ? await res.json().catch(() => ({})) : {}
      setRows(was)
      return setError(`${row ? `${row.fullName}: ` : ''}${body.error ?? (decision === 'approve' ? "that approval didn't go through. Try again." : "that didn't go through. Try again.")}`)
    }
  }

  if (rows.length === 0) {
    return (
      <p className="rounded-xl bg-[var(--surface-2)] p-5 text-center text-sm text-ink-2">
        Nobody waiting. New requests land here the moment someone taps your team link.
      </p>
    )
  }

  return (
    <div className="flex flex-col gap-3">
      {error && <p className="text-sm ">{error}</p>}

      {rows.map((r) => (
        <article key={r.id} className="rounded-xl border border-[var(--line)] p-4">
          <div className="font-semibold">{r.fullName}</div>
          <div className="mt-0.5 text-sm text-ink-2">
            {[r.team ?? r.academy, r.phone].filter(Boolean).join(' · ')}
          </div>
          {r.children.length > 0 && (
            <div className="mt-1 text-sm text-ink-2">
              Children: {r.children.join(', ')}
            </div>
          )}

          {/* Nothing about this person is verified. The coach knowing them is
              the check, so the screen shows exactly what they typed and no
              more — no green ticks implying we checked something. */}
          <div className="mt-3 flex gap-2">
            <button
              onClick={() => decide(r.id, 'approve')}
              disabled={busyId === r.id}
              className="flex-1 rounded-lg px-3 py-2.5 text-sm font-semibold text-brand-ink disabled:opacity-50"
              style={{ background: 'var(--brand)' }}
            >
              {busyId === r.id ? 'Working…' : 'Approve'}
            </button>
            <button
              onClick={() => decide(r.id, 'decline')}
              disabled={busyId === r.id}
              className="rounded-lg border border-[var(--line)] px-3 py-2.5 text-sm font-medium disabled:opacity-50"
            >
              Decline
            </button>
          </div>
        </article>
      ))}
    </div>
  )
}
